DO $$ DECLARE src text; BEGIN
SELECT pg_get_functiondef('public.hr_action(text,uuid,text,jsonb)'::regprocedure) INTO src;
src:=replace(src,'h:=jsonb_build_object', 'IF jsonb_typeof(_payload)<>''object'' THEN RAISE EXCEPTION ''Invalid payload''; END IF; IF _action NOT IN (''create'',''edit'') AND EXISTS(SELECT 1 FROM jsonb_object_keys(_payload) k WHERE k NOT IN (''note'',''interview_at'',''officer_id'',''method'')) THEN RAISE EXCEPTION ''Decision payload cannot edit records''; END IF; h:=jsonb_build_object');
src:=replace(src,'IF _module=''payroll'' AND', 'IF _module=''payroll'' THEN IF coalesce(d->>''currency'','''') NOT IN (''USD'',''LRD'') OR coalesce(d->>''period'','''') !~ ''^[0-9]{4}-(0[1-9]|1[0-2])$'' OR nullif(trim(d->>''salary_grade''),'''') IS NULL THEN RAISE EXCEPTION ''Payroll month, currency and salary grade required''; END IF; FOREACH k IN ARRAY ARRAY[''basic_salary'',''allowances'',''deductions'',''overtime''] LOOP IF coalesce(d->>k,'''') !~ ''^[0-9]+([.][0-9]{1,2})?$'' THEN RAISE EXCEPTION ''Valid payroll amounts required''; END IF; END LOOP; END IF; IF _module=''payroll'' AND');
src:=replace(src,'IF _module=''vacancies'' AND', 'IF _module=''vacancies'' AND (nullif(d->>''vacancy_number'','''') IS NULL OR nullif(d->>''position'','''') IS NULL OR nullif(d->>''posting_date'','''') IS NULL OR nullif(d->>''closing_date'','''') IS NULL OR nullif(d->>''number_required'','''') IS NULL) THEN RAISE EXCEPTION ''Complete vacancy information required''; END IF; IF _module=''vacancies'' AND');
src:=replace(src,'IF _module NOT IN (''vacancies'',''applicants'',''reports'') AND oid IS NULL', 'IF _module=''promotions'' AND (nullif(trim(d->>''new_rank''),'''') IS NULL OR nullif(d->>''effective_date'','''') IS NULL) THEN RAISE EXCEPTION ''Rank and effective date required''; END IF; IF _module=''transfers'' AND (nullif(d->>''effective_date'','''') IS NULL OR NOT EXISTS(SELECT 1 FROM sections WHERE id=nullif(d->>''section_id'','''')::uuid AND office_id=nullif(d->>''office_id'','''')::uuid)) THEN RAISE EXCEPTION ''Choose a unit in the selected department and an effective date''; END IF; IF _module NOT IN (''vacancies'',''applicants'',''reports'') AND oid IS NULL');
src:=replace(src,'oid:=nullif(_payload->>''officer_id'','''')::uuid;\n IF _action IN', 'oid:=nullif(_payload->>''officer_id'','''')::uuid; IF oid IS NULL THEN RAISE EXCEPTION ''Employee required''; END IF;\n IF _action IN');
src:=replace(src,'IF _payload->>''status'' NOT IN', 'IF nullif(_payload->>''attendance_date'','''') IS NULL OR nullif(_payload->>''status'','''') IS NULL THEN RAISE EXCEPTION ''Date and attendance status required''; END IF; IF _payload->>''status'' NOT IN');
EXECUTE src;
SELECT pg_get_functiondef('public.act_on_leave(uuid,boolean,text)'::regprocedure) INTO src;
src:=replace(src,'SELECT unnest(public.leave_stage_role(r.stage+1))', 'SELECT unnest(CASE WHEN r.workflow_kind=''HR'' THEN ARRAY[''hr_officer'',''hr_admin'']::public.app_role[] ELSE public.leave_stage_role(r.stage+1) END)');EXECUTE src;
END $$;
CREATE OR REPLACE FUNCTION public.hr_file_access(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT
 EXISTS(SELECT 1 FROM officer_documents d WHERE d.bucket_id='hr-files' AND d.file_url=_path AND public.hr_reader(d.officer_id))
 OR EXISTS(SELECT 1 FROM disciplinary_actions r CROSS JOIN LATERAL jsonb_array_elements(r.attachments) a WHERE a->>'path'=_path AND public.hr_reader(r.officer_id))
 OR EXISTS(SELECT 1 FROM training_records r CROSS JOIN LATERAL jsonb_array_elements(r.attachments) a WHERE a->>'path'=_path AND public.hr_reader(r.officer_id))
 OR EXISTS(SELECT 1 FROM recruitment_applicants r CROSS JOIN LATERAL jsonb_array_elements(r.attachments) a WHERE a->>'path'=_path AND public.hr_staff())
 OR EXISTS(SELECT 1 FROM leave_requests r CROSS JOIN LATERAL jsonb_array_elements(r.attachments) a WHERE a->>'path'=_path AND r.workflow_kind='HR' AND (public.hr_reader(r.officer_id) OR public.hr_head(r.officer_id))) $$;
DROP POLICY "staff read officer files" ON storage.objects;
CREATE POLICY officer_files_authorized_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='officer-files' AND (EXISTS(SELECT 1 FROM officers o WHERE o.photo_url=name AND public.hr_reader(o.id)) OR EXISTS(SELECT 1 FROM officer_documents d WHERE d.file_url=name AND d.bucket_id='officer-files' AND public.hr_reader(d.officer_id))));